class camera_ui(QThread, object):
    imageUpdate = pyqtSignal(QImage)
    redRise       = pyqtSignal()     # 🔔 phát 1 lần khi numb_red: 0→1
    yellowRise    = pyqtSignal()
    blueRise      = pyqtSignal()
    noneSeen    = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.threadActive = False
        # trạng thái trước để bắt rising edge
        self.prev_red = 0
        self.prev_yellow = 0
        self.prev_blue = 0
        self.cap = None

    def run(self, ):
        from imageprocess import detect_colors
        global numb_red, numb_blue, numb_yellow, cam_index
        self.threadActive = True
        cap = cv2.VideoCapture(cam_index)
        while self.threadActive:
            ret, frame = cap.read()
            ##chỉnh lại roi frame
            #cv2.rectangle(frame,(200,150), (1050,465), (255,0,0),2)
            if ret:
             annotated, numb_red, numb_blue, numb_yellow = detect_colors(frame)
             image = cv2.cvtColor(annotated, cv2.COLOR_BGR2RGB)
             converttoQtFormat = QImage(image.data, image.shape[1], image.shape[0], QImage.Format_RGB888)   
             pic = converttoQtFormat.scaled(550, 440, Qt.KeepAspectRatio)
             self.imageUpdate.emit(pic)
             if numb_red == 1 and self.prev_red == 0:
                self.redRise.emit()
            if numb_yellow == 1 and self.prev_yellow == 0:
                self.yellowRise.emit()
            if numb_blue == 1 and self.prev_blue == 0:
                self.blueRise.emit()
            # 🔔 nếu không thấy vật nào trong frame
            if (numb_red == 0) and (numb_blue == 0) and (numb_yellow == 0):
                self.noneSeen.emit()

            # cập nhật trạng thái
            self.prev_red, self.prev_yellow, self.prev_blue = numb_red, numb_yellow, numb_blue

        #key
        if self.threadActive:
             pass
        else:
             None
    def stop(self):
        self.threadActive = False
        self.wait()

